// Package pyjson reproduces, byte for byte, what Python's json.dumps and
// round() produce. Every preset generated by a scripts/build_*.py was
// written by Python; porting a script to Go keeps the generated file
// identical only if floats are printed as repr(float) and rounded as
// round(x, n). This package is that contract, and its tests pin it.
package pyjson

import (
	"encoding/json"
	"fmt"
	"math"
	"strconv"
	"strings"
	"unicode/utf8"
)

// Float formats v as Python's repr(float): shortest round-trip digits,
// fixed notation when the decimal exponent is in [-4, 16), a trailing
// ".0" on integral values, and "1e+16" / "1.5e-05" style otherwise.
// NaN and infinities are spelled as json.dumps spells them.
func Float(v float64) string {
	switch {
	case math.IsNaN(v):
		return "NaN"
	case math.IsInf(v, 1):
		return "Infinity"
	case math.IsInf(v, -1):
		return "-Infinity"
	case v == 0:
		if math.Signbit(v) {
			return "-0.0"
		}
		return "0.0"
	}
	s := strconv.FormatFloat(v, 'e', -1, 64) // e.g. "-1.2345e+01"
	sign := ""
	if s[0] == '-' {
		sign, s = "-", s[1:]
	}
	epos := strings.IndexByte(s, 'e')
	digits := strings.Replace(s[:epos], ".", "", 1)
	exp, _ := strconv.Atoi(s[epos+1:])
	if exp >= -4 && exp < 16 {
		if exp < 0 {
			return sign + "0." + strings.Repeat("0", -exp-1) + digits
		}
		if len(digits) <= exp+1 {
			return sign + digits + strings.Repeat("0", exp+1-len(digits)) + ".0"
		}
		return sign + digits[:exp+1] + "." + digits[exp+1:]
	}
	m := digits[:1]
	if len(digits) > 1 {
		m += "." + digits[1:]
	}
	es := "+"
	if exp < 0 {
		es, exp = "-", -exp
	}
	return fmt.Sprintf("%s%se%s%02d", sign, m, es, exp)
}

// Round is Python's round(x, n) for n >= 0: the exact binary value of x
// correctly rounded to n decimals, exact ties to even.
func Round(x float64, n int) float64 {
	if math.IsNaN(x) || math.IsInf(x, 0) {
		return x
	}
	v, _ := strconv.ParseFloat(strconv.FormatFloat(x, 'f', n, 64), 64)
	return v
}

// KV is one key of an ordered object; Obj keeps insertion order like a
// Python dict.
type KV struct {
	K string
	V any
}

// Obj is an ordered JSON object.
type Obj []KV

// Opts mirrors json.dumps(separators=(Item, Key), ensure_ascii=ASCII,
// indent=Indent). With Indent > 0, Item is "," and a newline plus the
// indentation follows it, as Python does.
type Opts struct {
	Item, Key string
	ASCII     bool
	Indent    int
}

// Indented is json.dumps(x, indent=n) (ensure_ascii on).
func Indented(n int) Opts { return Opts{Item: ",", Key: ": ", ASCII: true, Indent: n} }

// Default is json.dumps(x) with no argument.
var Default = Opts{Item: ", ", Key: ": ", ASCII: true}

// Compact is json.dumps(x, ensure_ascii=False, separators=(",", ":")).
var Compact = Opts{Item: ",", Key: ":", ASCII: false}

// Dumps encodes v. Supported values: nil, bool, int, float64, string,
// Obj, []any, []float64, []int, []bool, []string, and pointers to
// float64 (nil = null). Anything else panics: a generator bug, not data.
func Dumps(v any, o Opts) string {
	var b strings.Builder
	enc(&b, v, o, 0)
	return b.String()
}

// Number re-emits a number read with json.Decoder.UseNumber the way Python
// writes back what json.loads read: an integer stays an integer (any
// size), anything with a fraction or an exponent becomes repr(float).
func Number(n json.Number) string {
	s := string(n)
	if strings.ContainsAny(s, ".eE") {
		f, err := strconv.ParseFloat(s, 64)
		if err != nil {
			panic(fmt.Sprintf("pyjson: bad number %q", s))
		}
		return Float(f)
	}
	if s == "-0" {
		return "0"
	}
	return s
}

func newline(b *strings.Builder, o Opts, level int) {
	if o.Indent > 0 {
		b.WriteByte('\n')
		b.WriteString(strings.Repeat(" ", o.Indent*level))
	}
}

func enc(b *strings.Builder, v any, o Opts, level int) {
	switch x := v.(type) {
	case nil:
		b.WriteString("null")
	case bool:
		if x {
			b.WriteString("true")
		} else {
			b.WriteString("false")
		}
	case int:
		b.WriteString(strconv.Itoa(x))
	case json.Number:
		b.WriteString(Number(x))
	case float64:
		b.WriteString(Float(x))
	case *float64:
		if x == nil {
			b.WriteString("null")
		} else {
			b.WriteString(Float(*x))
		}
	case string:
		Str(b, x, o.ASCII)
	case Obj:
		if len(x) == 0 {
			b.WriteString("{}")
			return
		}
		b.WriteByte('{')
		for i, kv := range x {
			if i > 0 {
				b.WriteString(o.Item)
			}
			newline(b, o, level+1)
			Str(b, kv.K, o.ASCII)
			b.WriteString(o.Key)
			enc(b, kv.V, o, level+1)
		}
		newline(b, o, level)
		b.WriteByte('}')
	case []any:
		list(b, len(x), func(i int) any { return x[i] }, o, level)
	case []float64:
		list(b, len(x), func(i int) any { return x[i] }, o, level)
	case []int:
		list(b, len(x), func(i int) any { return x[i] }, o, level)
	case []bool:
		list(b, len(x), func(i int) any { return x[i] }, o, level)
	case []string:
		list(b, len(x), func(i int) any { return x[i] }, o, level)
	default:
		panic(fmt.Sprintf("pyjson: unsupported type %T", v))
	}
}

func list(b *strings.Builder, n int, at func(int) any, o Opts, level int) {
	if n == 0 {
		b.WriteString("[]")
		return
	}
	b.WriteByte('[')
	for i := 0; i < n; i++ {
		if i > 0 {
			b.WriteString(o.Item)
		}
		newline(b, o, level+1)
		enc(b, at(i), o, level+1)
	}
	newline(b, o, level)
	b.WriteByte(']')
}

// Str writes a JSON string literal the way Python's json module does:
// only '"', '\\' and control characters are escaped (lowercase \u00xx,
// short forms for \b \f \n \r \t); with ascii, DEL and every non-ASCII
// rune too, as UTF-16 surrogate pairs above U+FFFF. '/' and '<>&' stay.
func Str(b *strings.Builder, s string, ascii bool) {
	b.WriteByte('"')
	for i := 0; i < len(s); {
		r, size := utf8.DecodeRuneInString(s[i:])
		i += size
		switch {
		case r == '"':
			b.WriteString(`\"`)
		case r == '\\':
			b.WriteString(`\\`)
		case r == '\n':
			b.WriteString(`\n`)
		case r == '\r':
			b.WriteString(`\r`)
		case r == '\t':
			b.WriteString(`\t`)
		case r == '\b':
			b.WriteString(`\b`)
		case r == '\f':
			b.WriteString(`\f`)
		case r < 0x20:
			fmt.Fprintf(b, `\u%04x`, r)
		case ascii && r >= 0x7f: // ensure_ascii escapes DEL too
			if r > 0xffff {
				r -= 0x10000
				fmt.Fprintf(b, `\u%04x\u%04x`, 0xd800+(r>>10), 0xdc00+(r&0x3ff))
			} else {
				fmt.Fprintf(b, `\u%04x`, r)
			}
		default:
			b.WriteRune(r)
		}
	}
	b.WriteByte('"')
}
